import { getAnnotation, invalidateAnnotation, } from '../../annotation/annotationState.js';
import { getSegmentation } from '../getSegmentation.js';
import { extractSegmentPolylines } from './extractSegmentPolylines.js';
import decimate from '../../../utilities/math/polyline/decimate.js';
import { getViewportsAssociatedToSegmentation, getViewportWithMatchingViewPlaneNormal, } from './getViewportAssociatedToSegmentation.js';
import { utilities as cornerstoneUtilities } from '@cornerstonejs/core';
const cs3dLogger = cornerstoneUtilities.logger.toolsLog.getLogger('stateManagement.segmentation.utilities.decimateContours');
export default function decimateContours(segmentationId, segmentIndex, options = { epsilon: 0.1 }) {
    const segmentation = getSegmentation(segmentationId);
    if (!segmentation) {
        cs3dLogger.warn(`Invalid segmentation given ${segmentationId}`);
        return;
    }
    if (!segmentation.representationData.Contour) {
        cs3dLogger.warn(`No contour representation found for segmentation ${segmentationId}`);
        return;
    }
    const viewports = getViewportsAssociatedToSegmentation(segmentationId);
    if (!viewports) {
        cs3dLogger.warn('No viewport associated to the segmentation found');
        return;
    }
    const polylinesCanvasMap = extractSegmentPolylines(segmentationId, segmentIndex);
    if (!polylinesCanvasMap) {
        cs3dLogger.warn(`Error extracting contour data from segment ${segmentIndex} in segmentation ${segmentationId}`);
        return;
    }
    const keys = Array.from(polylinesCanvasMap?.keys());
    for (const annotationUID of keys) {
        const annotation = getAnnotation(annotationUID);
        if (!annotation) {
            continue;
        }
        const polylineCanvas = polylinesCanvasMap.get(annotationUID);
        const decimatedPolyline2D = decimate(polylineCanvas, options.epsilon);
        const viewport = getViewportWithMatchingViewPlaneNormal(viewports, annotation);
        if (viewport) {
            annotation.data.contour.polyline = decimatedPolyline2D.map((point2D) => viewport.canvasToWorld(point2D));
            invalidateAnnotation(annotation);
        }
    }
}
